using System.Numerics;
using CodeBrix.Graphics3D.Gltf2.Schema2;
using GltfNode = CodeBrix.Graphics3D.Gltf2.Schema2.Node;

namespace CodeBrix.Graphics3D.Cycles.GltfRender;

/// <summary>
/// Builds a small procedural glTF model (generated by this code, no external asset): a ground
/// quad, one cube mesh shared by two nodes (instancing), four metallic-roughness materials
/// (diffuse, rough metal, emissive, alpha-blended) and a perspective camera, optionally with a
/// KHR_lights_punctual directional light.
/// </summary>
public static class SampleModel
{
    /// <summary>
    /// Creates the sample model.
    /// </summary>
    /// <param name="withSun">Adds a directional light; otherwise the converter adds its default sun.</param>
    /// <returns>The model.</returns>
    public static ModelRoot Create(bool withSun = false)
    {
        ModelRoot model = ModelRoot.CreateModel();
        Material ground = model.CreateMaterial("ground").WithPBRMetallicRoughness(new Vector4(.6f, .55f, .5f, 1), null, null, 0f, .8f);
        Material metal = model.CreateMaterial("metal").WithPBRMetallicRoughness(new Vector4(.9f, .7f, .3f, 1), null, null, .75f, .35f);
        Material glow = model.CreateMaterial("glow").WithPBRMetallicRoughness(new Vector4(.2f, .2f, .2f, 1), null, null, 0f, 1f)
            .WithChannelColor("Emissive", new Vector4(1f, .4f, .1f, 1));
        Material tinted = model.CreateMaterial("tinted").WithPBRMetallicRoughness(new Vector4(.2f, .5f, .9f, .5f), null, null, 0f, .5f);
        tinted.Alpha = AlphaMode.BLEND;

        Mesh quad = model.CreateMesh("ground");
        quad.CreatePrimitive()
            .WithVertexAccessor("POSITION", new[] { new Vector3(-3, 0, -3), new Vector3(3, 0, -3), new Vector3(3, 0, 3), new Vector3(-3, 0, 3) })
            .WithVertexAccessor("NORMAL", new[] { Vector3.UnitY, Vector3.UnitY, Vector3.UnitY, Vector3.UnitY })
            .WithVertexAccessor("TEXCOORD_0", new[] { new Vector2(0, 0), new Vector2(1, 0), new Vector2(1, 1), new Vector2(0, 1) })
            .WithIndicesAccessor(PrimitiveType.TRIANGLES, new[] { 0, 2, 1, 0, 3, 2 })
            .WithMaterial(ground);

        // A unit cube whose faces use two materials (two primitives in one mesh).
        Vector3[] corners =
        [
            new(-.5f, 0, -.5f), new(.5f, 0, -.5f), new(.5f, 1, -.5f), new(-.5f, 1, -.5f),
            new(-.5f, 0, .5f), new(.5f, 0, .5f), new(.5f, 1, .5f), new(-.5f, 1, .5f)
        ];
        Mesh cube = model.CreateMesh("cube");
        cube.CreatePrimitive().WithVertexAccessor("POSITION", corners)
            .WithIndicesAccessor(PrimitiveType.TRIANGLES, new[] { 4, 5, 6, 4, 6, 7, 1, 0, 3, 1, 3, 2, 5, 1, 2, 5, 2, 6 })
            .WithMaterial(metal);
        cube.CreatePrimitive().WithVertexAccessor("POSITION", corners)
            .WithIndicesAccessor(PrimitiveType.TRIANGLES, new[] { 0, 4, 7, 0, 7, 3, 3, 7, 6, 3, 6, 2, 0, 1, 5, 0, 5, 4 })
            .WithMaterial(glow);

        Mesh pane = model.CreateMesh("pane");
        pane.CreatePrimitive()
            .WithVertexAccessor("POSITION", new[] { new Vector3(-.6f, 0, 0), new Vector3(.6f, 0, 0), new Vector3(.6f, 1.2f, 0), new Vector3(-.6f, 1.2f, 0) })
            .WithIndicesAccessor(PrimitiveType.TRIANGLES, new[] { 0, 1, 2, 0, 2, 3 })
            .WithMaterial(tinted);

        Scene scene = model.UseScene("sample");
        scene.CreateNode("ground").WithMesh(quad);
        scene.CreateNode("cube-a").WithMesh(cube).WithLocalTranslation(new Vector3(-1, 0, 0));
        scene.CreateNode("cube-b").WithMesh(cube).WithLocalTranslation(new Vector3(1.2f, 0, -.5f)).WithLocalRotation(Quaternion.CreateFromYawPitchRoll(.6f, 0, 0));
        scene.CreateNode("pane").WithMesh(pane).WithLocalTranslation(new Vector3(.1f, 0, 1.2f));

        Camera camera = model.CreateCamera("camera");
        camera.SetPerspectiveMode(null, .9f, .1f, 100f);
        Matrix4x4 view = Matrix4x4.CreateLookAt(new Vector3(2.5f, 2.6f, 5.5f), new Vector3(0, .5f, 0), Vector3.UnitY);
        Matrix4x4.Invert(view, out Matrix4x4 cameraWorld);
        GltfNode cameraNode = scene.CreateNode("camera");
        cameraNode.Camera = camera;
        cameraNode.LocalMatrix = cameraWorld;

        if (withSun)
        {
            PunctualLight sun = model.CreatePunctualLight("sun", PunctualLightType.Directional);
            sun.SetColor(new Vector3(1f, .95f, .9f), 3f);
            GltfNode sunNode = scene.CreateNode("sun");
            sunNode.PunctualLight = sun;
            sunNode.LocalMatrix = Matrix4x4.CreateRotationX(-1.0f) * Matrix4x4.CreateRotationY(.4f);
        }
        return model;
    }
}
